import type { CareerState, OperatorId } from '../core/types';

const STORAGE_KEY = 'root-panic-career-v1';

const emptyXp = (): Record<OperatorId, number> => ({ sre: 0, devops: 0, secops: 0, dba: 0, network: 0 });

export const defaultCareer = (): CareerState => ({
  version: 1,
  knowledge: 0,
  totalRuns: 0,
  bestGrade: '-',
  operatorXp: emptyXp(),
  locale: 'zh-CN',
  reducedMotion: window.matchMedia('(prefers-reduced-motion: reduce)').matches,
  comfortableText: true,
  audioEnabled: true,
  hqLevel: 1,
  unlockedScenarios: ['ghost-traffic', 'ghost-commit'],
  achievements: [],
  skillPoints: 2,
  unlockedSkills: [],
  tutorialCompleted: false,
  aiArchives: [],
  runHistory: [],
  dailyBest: {},
});

export const loadCareer = (): CareerState => {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return defaultCareer();
    return { ...defaultCareer(), ...JSON.parse(raw) } as CareerState;
  } catch {
    return defaultCareer();
  }
};

export const saveCareer = (career: CareerState): void => {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(career));
};

export const exportCareer = (career: CareerState): string => btoa(unescape(encodeURIComponent(JSON.stringify(career))));

export const importCareer = (encoded: string): CareerState => {
  const parsed = JSON.parse(decodeURIComponent(escape(atob(encoded.trim())))) as Partial<CareerState>;
  if (parsed.version !== 1 || typeof parsed.knowledge !== 'number') throw new Error('Invalid ROOT//PANIC save data');
  return { ...defaultCareer(), ...parsed } as CareerState;
};
