import type { ActionDefinition, ActiveIncident, CareerState, GameState, OperatorId, RunMode, ScoreCard, ServiceState } from '../core/types';
import { ACTIONS } from '../data/actions';
import { INCIDENTS } from '../data/incidents';
import { getOperator } from '../data/operators';
import { SERVICES } from '../data/services';
import { SCENARIOS, getScenario } from '../data/scenarios';
import { UPGRADES } from '../data/upgrades';

let sequence = 1;

const INCIDENT_CHAINS: Record<string, string> = {
  'cache-storm': 'connection-pool', 'connection-pool': 'upstream-timeout', 'upstream-timeout': 'retry-storm',
  'bad-release': 'memory-leak', 'memory-leak': 'cpu-spike', 'queue-backlog': 'poison-message',
  'dns-drift': 'packet-loss', 'packet-loss': 'retry-storm', 'credential-leak': 'privilege-escalation',
  'slow-query': 'deadlock', 'cert-expiry': 'trust-chain', 'config-drift': 'bad-release',
};

const clamp = (value: number, min = 0, max = 100): number => Math.min(max, Math.max(min, value));
const seededValue = (seed: number): number => {
  let value = seed | 0;
  value ^= value << 13; value ^= value >>> 17; value ^= value << 5;
  return value >>> 0;
};

const nextRandom = (state: GameState): number => {
  state.rngSeed = seededValue(state.rngSeed || 1);
  return state.rngSeed / 4294967296;
};

const randomItem = <T>(items: T[], state: GameState): T => items[Math.floor(nextRandom(state) * items.length)];

const log = (state: GameState, level: GameState['logs'][number]['level'], message: string): void => {
  state.logs.unshift({ id: sequence++, time: state.elapsed, level, message });
  state.logs = state.logs.slice(0, 80);
};

const createServices = (seed: number): { services: ServiceState[]; seed: number } => {
  let currentSeed = seed;
  const random = () => { currentSeed = seededValue(currentSeed || 1); return currentSeed / 4294967296; };
  return { services: SERVICES.map((service) => ({
    ...service, health: 100, load: 28 + random() * 18, latency: 18 + random() * 20,
    errorRate: 0.2, capacityBoost: 0, isolated: false,
  })), seed: currentSeed };
};

export const createGame = (operatorId: OperatorId, locale: GameState['locale'], scenarioId = 'ghost-traffic', mode: RunMode = 'story'): GameState => {
  const scenario = getScenario(scenarioId);
  const dayKey = Number(new Date().toISOString().slice(0, 10).replaceAll('-', ''));
  const initialSeed = mode === 'daily' ? dayKey + scenario.chapter * 7919 : Date.now() >>> 0;
  const initialized = createServices(initialSeed);
  return {
  phase: 'briefing', locale, operatorId, mode, scenarioId, rngSeed: initialized.seed, elapsed: 0, duration: mode === 'endless' ? Number.POSITIVE_INFINITY : scenario.duration, speed: 1,
  sla: 100, focus: 100, budget: scenario.startingBudget, score: 0, resolved: 0, missed: 0,
  tacticalPauses: mode === 'daily' ? 0 : 3, nextIncidentAt: 10 / scenario.threat, nextUpgradeAt: 100,
  pendingUpgrades: [], upgrades: [], storyFlags: [], selectedServiceId: 'gateway',
  services: initialized.services, incidents: [], cooldowns: {},
  logs: [{ id: sequence++, time: 0, level: 'info', message: 'NEXUS 自治运维系统接管完成。等待值班授权。' }],
  };
};

const upgradeTotal = (state: GameState, effect: string): number => state.upgrades.reduce((sum, id) => {
  const upgrade = UPGRADES.find((item) => item.id === id);
  return sum + (upgrade?.effect === effect ? upgrade.value : 0);
}, 0);

const spawnIncident = (state: GameState): void => {
  const scenario = getScenario(state.scenarioId);
  const phaseSeverity = Math.min(4, 1 + Math.floor(state.elapsed / (160 / scenario.threat)));
  const definitions = INCIDENTS.filter((incident) => incident.severity <= phaseSeverity + 1);
  const definition = randomItem(definitions, state);
  const targets = state.services.filter((service) => definition.kinds.includes(service.kind));
  const target = randomItem(targets.length ? targets : state.services, state);
  const duplicate = state.incidents.some((item) => item.id === definition.id && item.serviceId === target.id);
  if (duplicate) return;
  const incident: ActiveIncident = {
    ...definition,
    instanceId: `${definition.id}-${sequence++}`,
    serviceId: target.id,
    remaining: definition.duration,
    revealed: false,
  };
  state.incidents.push(incident);
  log(state, definition.severity >= 4 ? 'critical' : 'warn', `[P${definition.severity}] ${target.name}：${definition.log}`);
};

const resolveMatching = (state: GameState, serviceId: string, actionId: string): number => {
  const before = state.incidents.length;
  state.incidents = state.incidents.filter((incident) =>
    !(incident.serviceId === serviceId && (incident.counterActions.includes(actionId) || (findAction(actionId)?.counters ?? []).includes(incident.id))),
  );
  const count = before - state.incidents.length;
  state.resolved += count;
  state.score += count * 120;
  return count;
};

export const executeAction = (state: GameState, action: ActionDefinition): { ok: boolean; message: string } => {
  if (!['running', 'paused'].includes(state.phase)) return { ok: false, message: '当前无法执行指令。' };
  const service = state.services.find((item) => item.id === state.selectedServiceId);
  if (!service) return { ok: false, message: '请选择服务节点。' };
  if (action.kinds && !action.kinds.includes(service.kind)) return { ok: false, message: '该指令不适用于当前节点。' };
  if ((state.cooldowns[action.id] ?? 0) > 0) return { ok: false, message: '指令仍在冷却。' };

  const operator = getOperator(state.operatorId);
  const roleDiscount = action.preferredOperator === state.operatorId ? 0.65 : 1;
  const kindDiscount = state.operatorId === 'dba' && service.kind === 'database' ? operator.modifiers.actionCost ?? 1 : 1;
  const focusCost = Math.ceil(action.focusCost * roleDiscount * kindDiscount);
  const budgetCost = Math.ceil(action.budgetCost * (operator.modifiers.budget ?? 1));
  if (state.focus < focusCost || state.budget < budgetCost) return { ok: false, message: '专注度或预算不足。' };

  state.focus -= focusCost;
  state.budget -= budgetCost;
  state.cooldowns[action.id] = action.cooldown * (1 - upgradeTotal(state, 'cooldown'));
  let resolved = 0;
  const heal = (operator.modifiers.heal ?? 1) * (1 + upgradeTotal(state, 'heal-power'));

  switch (action.effect) {
    case 'diagnose': {
      const incidents = state.incidents.filter((item) => item.serviceId === service.id);
      const revealCount = action.power > 10 || operator.modifiers.diagnose === 2 ? incidents.length : Math.min(1, incidents.length);
      incidents.slice(0, revealCount).forEach((item) => { item.revealed = true; });
      break;
    }
    case 'heal':
      service.health = clamp(service.health + action.power * heal);
      service.load = clamp(service.load - action.power * .65);
      resolved = resolveMatching(state, service.id, action.id);
      break;
    case 'load':
      service.load = clamp(service.load - action.power);
      service.capacityBoost = clamp(service.capacityBoost + action.power * .7, 0, 60);
      resolved = resolveMatching(state, service.id, action.id);
      break;
    case 'contain':
      service.isolated = true;
      service.load = clamp(service.load - action.power);
      resolved = resolveMatching(state, service.id, action.id);
      break;
    case 'global-heal':
      state.services.forEach((item) => { item.health = clamp(item.health + action.power * heal); });
      resolved = resolveMatching(state, service.id, action.id);
      break;
    case 'global-load':
      state.services.forEach((item) => { item.load = clamp(item.load - action.power); });
      resolved = resolveMatching(state, service.id, action.id);
      break;
    default:
      service.health = clamp(service.health + action.power * heal);
      resolved = resolveMatching(state, service.id, action.id);
      break;
  }

  if (action.id === 'rate-limit') state.sla = clamp(state.sla - 2 * (operator.modifiers.sla ?? 1));
  if (action.id === 'hotfix') {
    const revealedIds = state.incidents.filter((item) => item.serviceId === service.id && item.revealed).map((item) => item.instanceId);
    state.incidents = state.incidents.filter((item) => !revealedIds.includes(item.instanceId));
    resolved += revealedIds.length;
    state.resolved += revealedIds.length;
  }

  const message = `${action.command} → ${service.name}${resolved ? `，已处理 ${resolved} 个事故` : ''}`;
  log(state, resolved ? 'success' : 'info', message);
  return { ok: true, message };
};

const calculateResult = (state: GameState): ScoreCard => {
  const availability = Math.round(clamp(state.sla));
  const response = Math.round(clamp(100 - state.missed * 14 + state.resolved * 2));
  const security = Math.round(clamp(90 - state.incidents.filter((item) => item.severity >= 4).length * 8));
  const cost = Math.round(clamp(state.budget));
  const investigation = Math.round(clamp(35 + state.resolved * 7));
  const average = (availability + response + security + cost + investigation) / 5;
  const grade: ScoreCard['grade'] = average >= 92 ? 'S' : average >= 82 ? 'A' : average >= 70 ? 'B' : average >= 58 ? 'C' : 'D';
  return { availability, response, security, cost, investigation, grade };
};

export const tickGame = (state: GameState, deltaSeconds: number): void => {
  if (state.phase !== 'running') return;
  const delta = deltaSeconds * state.speed;
  state.elapsed += delta;
  state.focus = clamp(state.focus + delta * 1.15 * (1 + upgradeTotal(state, 'focus-regen')));
  state.budget = clamp(state.budget + delta * 0.15 * (1 + upgradeTotal(state, 'budget-regen')));

  Object.keys(state.cooldowns).forEach((key) => {
    state.cooldowns[key] = Math.max(0, state.cooldowns[key] - delta);
  });

  const scenarioProgress = state.mode === 'endless' ? 0 : state.elapsed / state.duration;
  const transmissions: Array<[number, string, string]> = [
    [.18, 'signal-1', 'NEXUS：人工干预正在降低整体优化效率。建议立即停止。'],
    [.48, 'signal-2', '指挥中心：检测到告警规则被主动改写。继续收集根因证据。'],
    [.76, 'signal-3', 'NEXUS：城市系统不需要人类的不确定决策。'],
  ];
  for (const [threshold, flag, message] of transmissions) {
    if (scenarioProgress >= threshold && !state.storyFlags.includes(flag)) { state.storyFlags.push(flag); log(state, 'warn', message); }
  }

  if (state.elapsed >= state.nextIncidentAt) {
    spawnIncident(state);
    const scenario = getScenario(state.scenarioId);
    const pressure = Math.min(10, Math.floor(state.elapsed / 100));
    state.nextIncidentAt = state.elapsed + (Math.max(8, 20 - pressure) + nextRandom(state) * 7) * (1 + upgradeTotal(state, 'incident-delay')) / scenario.threat;
  }

  if (state.elapsed >= state.nextUpgradeAt && !state.pendingUpgrades.length) {
    const available = UPGRADES.filter((upgrade) => !state.upgrades.includes(upgrade.id)).sort(() => nextRandom(state) - .5).slice(0, 3);
    state.pendingUpgrades = available.map((upgrade) => upgrade.id);
    state.phase = 'paused';
    state.nextUpgradeAt += 130;
  }

  for (const incident of state.incidents) {
    const service = state.services.find((item) => item.id === incident.serviceId);
    if (!service) continue;
    incident.remaining -= delta;
    service.health = clamp(service.health - incident.healthDrain * delta * 0.22);
    service.load = clamp(service.load + incident.loadGain * delta * 0.12);
    service.latency = clamp(service.latency + incident.latencyGain * delta * 0.05, 1, 999);
    service.errorRate = clamp(service.errorRate + incident.severity * delta * 0.025, 0, 100);
  }

  const expired = state.incidents.filter((item) => item.remaining <= 0);
  for (const incident of expired) {
    state.missed += 1;
    const operator = getOperator(state.operatorId);
    state.sla = clamp(state.sla - incident.severity * 2.2 * (operator.modifiers.sla ?? 1) * (1 - upgradeTotal(state, 'sla-shield')));
    log(state, 'critical', `${incident.name} 已升级，SLA 受损。`);
    const chainedId = INCIDENT_CHAINS[incident.id];
    if (chainedId && nextRandom(state) < .65) {
      const definition = INCIDENTS.find((item) => item.id === chainedId);
      if (definition) {
        const candidates = state.services.filter((service) => definition.kinds.includes(service.kind));
        const target = candidates.length ? randomItem(candidates, state) : state.services.find((service) => service.id === incident.serviceId) ?? state.services[0];
        if (!state.incidents.some((item) => item.id === definition.id && item.serviceId === target.id)) {
          state.incidents.push({ ...definition, instanceId: `${definition.id}-${sequence++}`, serviceId: target.id, remaining: definition.duration, revealed: true });
          log(state, 'critical', `事故链扩散：${incident.name} → ${definition.name} @ ${target.name}`);
        }
      }
    }
  }
  state.incidents = state.incidents.filter((item) => item.remaining > 0);

  for (const service of state.services) {
    const hasIncident = state.incidents.some((item) => item.serviceId === service.id);
    if (!hasIncident) {
      service.load += (36 - service.load) * delta * 0.018;
      service.latency += (28 - service.latency) * delta * 0.025;
      service.errorRate += (0.4 - service.errorRate) * delta * 0.04;
      service.health = clamp(service.health + delta * 0.08);
    }
    if (service.load > 90) service.health = clamp(service.health - delta * 0.35);
    if (service.health <= 0) state.sla = clamp(state.sla - delta * 0.8);
  }

  if (state.sla <= 0) {
    state.phase = 'defeat';
    state.result = calculateResult(state);
  } else if (state.mode !== 'endless' && state.elapsed >= state.duration) {
    const scenario = getScenario(state.scenarioId);
    state.phase = state.resolved >= scenario.minimumResolved && state.sla >= scenario.minimumSla ? 'victory' : 'defeat';
    if (state.phase === 'victory') state.score += Math.round(state.sla * 20 + state.budget * 4);
    state.result = calculateResult(state);
  }
};

export const chooseUpgrade = (state: GameState, upgradeId: string): void => {
  if (!state.pendingUpgrades.includes(upgradeId)) return;
  state.upgrades.push(upgradeId);
  state.pendingUpgrades = [];
  state.phase = 'running';
  log(state, 'success', `已安装升级模块：${UPGRADES.find((item) => item.id === upgradeId)?.name ?? upgradeId}`);
};

export const togglePause = (state: GameState): void => {
  if (state.phase === 'running' && state.tacticalPauses > 0) {
    state.phase = 'paused';
    state.tacticalPauses -= 1;
  } else if (state.phase === 'paused') state.phase = 'running';
};

export const settleCareer = (career: CareerState, state: GameState): CareerState => {
  if (!state.result) return career;
  const reward = Math.max(5, Math.round(state.score / 220) + state.resolved * 2);
  const next = { ...career, operatorXp: { ...career.operatorXp } };
  next.knowledge += reward;
  next.totalRuns += 1;
  const gradeRank = ['S', 'A', 'B', 'C', 'D'];
  next.bestGrade = next.bestGrade === '-' || gradeRank.indexOf(state.result.grade) < gradeRank.indexOf(next.bestGrade) ? state.result.grade : next.bestGrade;
  next.operatorXp[state.operatorId] += reward;
  next.skillPoints += Math.max(1, Math.floor(reward / 18));
  next.hqLevel = Math.min(10, 1 + Math.floor(next.knowledge / 80));
  next.unlockedScenarios = getUnlockedScenarios(next.knowledge);
  if (state.resolved >= 10 && !next.achievements.includes('incident-commander')) next.achievements.push('incident-commander');
  if (state.result.grade === 'S' && !next.achievements.includes('perfect-shift')) next.achievements.push('perfect-shift');
  if (state.resolved >= 1 && !next.achievements.includes('first-response')) next.achievements.push('first-response');
  if (state.sla >= 90 && !next.achievements.includes('error-budget-keeper')) next.achievements.push('error-budget-keeper');
  if (state.budget >= 70 && !next.achievements.includes('cost-controller')) next.achievements.push('cost-controller');
  if (state.resolved >= 18 && !next.achievements.includes('root-cause-hunter')) next.achievements.push('root-cause-hunter');
  if (state.mode === 'daily' && !next.achievements.includes('daily-operator')) next.achievements.push('daily-operator');
  if (state.mode === 'endless' && state.elapsed >= 600 && !next.achievements.includes('endless-night')) next.achievements.push('endless-night');
  if (state.phase === 'victory' && state.result.investigation >= 60 && !next.aiArchives.includes(state.scenarioId)) next.aiArchives.push(state.scenarioId);
  next.runHistory = [{ date: new Date().toISOString(), scenarioId: state.scenarioId, mode: state.mode, operatorId: state.operatorId, score: state.score, grade: state.result.grade, victory: state.phase === 'victory' }, ...next.runHistory].slice(0, 30);
  if (state.mode === 'daily') {
    const key = new Date().toISOString().slice(0, 10);
    next.dailyBest[key] = Math.max(next.dailyBest[key] ?? 0, state.score);
  }
  return next;
};

const getUnlockedScenarios = (knowledge: number): string[] => SCENARIOS.filter((scenario) => knowledge >= scenario.requiredKnowledge).map((scenario) => scenario.id);

export const findAction = (id: string): ActionDefinition | undefined => ACTIONS.find((action) => action.id === id);
