import type { DebugEvidenceId, DebugMissionState } from '../core/types';
import { getDebugPatch } from '../data/debugMissions';

export type DebugActionId = 'inspect-logs' | 'trace-call' | 'run-tests' | 'git-bisect';

const addEvidence = (state: DebugMissionState, evidence: DebugEvidenceId): void => {
  if (!state.evidence.includes(evidence)) state.evidence.push(evidence);
};

const pushLog = (state: DebugMissionState, level: DebugMissionState['logs'][number]['level'], message: string): void => {
  state.logs.unshift({ level, message });
  state.logs = state.logs.slice(0, 30);
};

export const createDebugMission = (duration = 480): DebugMissionState => ({
  elapsed: 0,
  duration,
  stability: 100,
  selectedFileId: 'create-order',
  selectedCommitId: '7fa21c8',
  evidence: [],
  tests: 'idle',
  attempts: 0,
  logs: [{ level: 'info', message: 'CI 沙箱已连接。等待调查指令。' }],
});

export const tickDebugMission = (state: DebugMissionState, deltaSeconds: number): 'running' | 'defeat' => {
  state.elapsed += deltaSeconds;
  if (state.elapsed >= state.duration || state.stability <= 0) return 'defeat';
  return 'running';
};

export const executeDebugAction = (state: DebugMissionState, action: DebugActionId): string => {
  switch (action) {
    case 'inspect-logs':
      addEvidence(state, 'retry-window');
      pushLog(state, 'warn', '两个订单拥有相同 requestId，写入间隔仅 37ms。');
      return '日志已关联：重复写入发生在同一次 Webhook 重试窗口。';
    case 'trace-call':
      addEvidence(state, 'double-entry');
      pushLog(state, 'warn', 'paymentWebhook → retry.withBackoff → createOrder 被并发调用两次。');
      return '调用栈已还原：重试器可能并发进入订单创建逻辑。';
    case 'git-bisect':
      addEvidence(state, 'bad-commit');
      state.selectedCommitId = '7fa21c8';
      pushLog(state, 'critical', '7fa21c8 是首个失败提交：optimize webhook retry path。');
      return '二分完成：异常由提交 7fa21c8 首次引入。';
    case 'run-tests': {
      addEvidence(state, 'test-gap');
      const patch = getDebugPatch(state.selectedPatchId);
      state.tests = patch?.correct ? 'passing' : patch ? 'failing' : 'baseline-failing';
      if (state.tests === 'passing') {
        pushLog(state, 'success', '8/8 tests passed，包括并发重试与正常重复购买。');
        return '回归测试全部通过，可以部署补丁。';
      }
      state.stability = Math.max(0, state.stability - 4);
      pushLog(state, 'critical', patch ? '7/8 tests passed：补丁未解决并发幂等问题。' : '7/8 tests passed：order.retry.test.ts 失败。');
      return patch ? '测试失败：当前补丁没有修复真正根因。' : '基线测试完成：并发重试用例失败。';
    }
  }
};

export const selectDebugPatch = (state: DebugMissionState, patchId: string): { ok: boolean; message: string } => {
  if (state.evidence.length < 2) return { ok: false, message: '证据不足：至少完成两项调查后才能安全修改代码。' };
  const patch = getDebugPatch(patchId);
  if (!patch) return { ok: false, message: '补丁不存在。' };
  state.selectedPatchId = patchId;
  state.tests = 'idle';
  pushLog(state, 'info', `补丁已暂存：${patch.name}。请运行回归测试。`);
  return { ok: true, message: `已应用“${patch.name}”，请运行测试后部署。` };
};

export const deployDebugPatch = (state: DebugMissionState): { outcome: 'continue' | 'victory' | 'defeat'; message: string } => {
  const patch = getDebugPatch(state.selectedPatchId);
  if (!patch) return { outcome: 'continue', message: '尚未选择补丁。' };
  if (state.tests !== 'passing' || !patch.correct) {
    state.attempts += 1;
    state.stability = Math.max(0, state.stability - 24);
    pushLog(state, 'critical', '部署门禁拒绝：回归测试没有全部通过。');
    return { outcome: state.stability <= 0 ? 'defeat' : 'continue', message: '部署被拒绝，稳定度下降。重新检查证据和补丁。' };
  }
  pushLog(state, 'success', '补丁部署完成，重复订单停止增长。NEXUS 提交签名已归档。');
  return { outcome: 'victory', message: '根因已修复：幂等判断遗漏了 processing 状态。' };
};
