export class AudioDirector {
  private context?: AudioContext;
  private master?: GainNode;
  private drone?: OscillatorNode;
  private pulse?: OscillatorNode;
  private enabled = true;

  start(): void {
    if (this.context) { void this.context.resume(); return; }
    const AudioContextClass = window.AudioContext;
    this.context = new AudioContextClass();
    this.master = this.context.createGain();
    this.master.gain.value = .035;
    this.master.connect(this.context.destination);
    this.drone = this.context.createOscillator();
    this.drone.type = 'sine'; this.drone.frequency.value = 54;
    const droneGain = this.context.createGain(); droneGain.gain.value = .35;
    this.drone.connect(droneGain).connect(this.master); this.drone.start();
    this.pulse = this.context.createOscillator();
    this.pulse.type = 'square'; this.pulse.frequency.value = 1.2;
    const pulseGain = this.context.createGain(); pulseGain.gain.value = .06;
    this.pulse.connect(pulseGain).connect(this.master); this.pulse.start();
  }

  setEnabled(enabled: boolean): void {
    this.enabled = enabled;
    if (this.master && this.context) this.master.gain.setTargetAtTime(enabled ? .035 : 0, this.context.currentTime, .04);
  }

  update(pressure: number): void {
    if (!this.context || !this.master || !this.enabled) return;
    const normalized = Math.min(1, Math.max(0, pressure));
    this.master.gain.setTargetAtTime(.025 + normalized * .028, this.context.currentTime, .3);
    this.drone?.frequency.setTargetAtTime(54 + normalized * 28, this.context.currentTime, .4);
    this.pulse?.frequency.setTargetAtTime(1.2 + normalized * 3.8, this.context.currentTime, .3);
  }

  cue(type: 'success' | 'warn' | 'error' | 'select'): void {
    if (!this.context || !this.master || !this.enabled) return;
    const now = this.context.currentTime;
    const oscillator = this.context.createOscillator();
    const gain = this.context.createGain();
    const frequencies = { success: 620, warn: 330, error: 120, select: 480 };
    oscillator.type = type === 'error' ? 'sawtooth' : 'sine';
    oscillator.frequency.setValueAtTime(frequencies[type], now);
    oscillator.frequency.exponentialRampToValueAtTime(frequencies[type] * (type === 'success' ? 1.5 : .75), now + .12);
    gain.gain.setValueAtTime(.15, now); gain.gain.exponentialRampToValueAtTime(.001, now + .16);
    oscillator.connect(gain).connect(this.master); oscillator.start(now); oscillator.stop(now + .17);
  }
}
