export interface DebugFileDefinition {
  id: string;
  path: string;
  language: string;
  content: string[];
  suspiciousLines?: number[];
}

export interface DebugCommitDefinition {
  id: string;
  author: string;
  message: string;
  time: string;
  suspicious?: boolean;
}

export interface DebugPatchDefinition {
  id: string;
  name: string;
  nameEn: string;
  summary: string;
  summaryEn: string;
  diff: string[];
  correct: boolean;
}

