export const getDebugFile = (id: string): DebugFileDefinition => DEBUG_FILES.find((file) => file.id === id) ?? DEBUG_FILES[0];
export const getDebugCommit = (id: string): DebugCommitDefinition => DEBUG_COMMITS.find((commit) => commit.id === id) ?? DEBUG_COMMITS[0];
export const getDebugPatch = (id?: string): DebugPatchDefinition | undefined => DEBUG_PATCHES.find((patch) => patch.id === id);
