  private debugHintPanel(): string {
    const evidence = this.debugState?.evidence.length ?? 0;
    const steps = evidence < 2
      ? [this.local('先执行“关联日志”和“追踪调用栈”。', 'Start with Correlate Logs and Trace Call Stack.'), this.local('点击文件和提交记录查看代码上下文。', 'Inspect files and commits for context.')]
      : !this.debugState?.selectedPatchId
        ? [this.local('证据已经足够，比较三个候选补丁。', 'You have enough evidence. Compare the three patches.'), this.local('不要用延迟掩盖并发问题，也不要按用户错误去重。', 'Do not hide the race with a delay or deduplicate by user.')]
        : this.debugState.tests !== 'passing'
          ? [this.local('运行并发回归测试验证当前补丁。', 'Run the race-condition regression test.'), this.local('只有 8/8 通过后才能安全部署。', 'Deploy only after all 8 tests pass.')]
          : [this.local('测试已经全部通过，现在部署补丁。', 'All tests pass. Deploy the patch now.')];
    return `<div class="hint-drawer"><header><div><span class="eyebrow">DEBUG ASSISTANT</span><h2>${this.local('幽灵提交调查', 'GHOST COMMIT INVESTIGATION')}</h2></div><button data-action="close-debug-hint">×</button></header><p>${this.local('目标：找到重复订单的真正根因，提交通过并发测试的最小修复。', 'Find the true cause of duplicate orders and ship the smallest patch that passes concurrency tests.')}</p><ol>${steps.map((step) => `<li>${esc(step)}</li>`).join('')}</ol><div class="hint-objective"><span>EVIDENCE</span><b>${evidence}/4</b><span>STABILITY ${Math.round(this.debugState?.stability ?? 0)}%</span></div></div>`;
  }

  private finishDebugMission(victory: boolean): void {
    if (!this.debugState || ['victory', 'defeat'].includes(this.game.phase)) return;
    const state = this.debugState;
    const investigation = Math.round(state.evidence.length * 25);
    const response = Math.round(Math.max(0, 100 - state.elapsed / state.duration * 65));
    const cost = Math.max(0, 100 - state.attempts * 25);
    const availability = Math.round(state.stability);
    const security = victory ? 96 : 55;
    const average = (availability + response + security + cost + investigation) / 5;
    const grade = average >= 92 ? 'S' : average >= 82 ? 'A' : average >= 70 ? 'B' : average >= 58 ? 'C' : 'D';
    this.game.sla = state.stability;
    this.game.budget = cost;
    this.game.resolved = victory ? 1 : 0;
    this.game.score = victory ? Math.round(900 + state.stability * 8 + (state.duration - state.elapsed) * 2) : Math.round(investigation * 2);
    this.game.phase = victory ? 'victory' : 'defeat';
    this.game.result = { availability, response, security, cost, investigation, grade };
  }

  private bindDebugEvents(): void {
    if (!this.debugState) return;
    this.root.querySelectorAll<HTMLElement>('[data-debug-file]').forEach((button) => button.addEventListener('click', () => { if (this.debugState) this.debugState.selectedFileId = button.dataset.debugFile ?? this.debugState.selectedFileId; this.render(); }));
    this.root.querySelectorAll<HTMLElement>('[data-debug-commit]').forEach((button) => button.addEventListener('click', () => { if (this.debugState) this.debugState.selectedCommitId = button.dataset.debugCommit ?? this.debugState.selectedCommitId; this.render(); }));
    this.root.querySelectorAll<HTMLElement>('[data-debug-action]').forEach((button) => button.addEventListener('click', () => { if (!this.debugState) return; this.showToast(executeDebugAction(this.debugState, button.dataset.debugAction as DebugActionId)); this.render(); }));
    this.root.querySelectorAll<HTMLElement>('[data-debug-patch]').forEach((button) => button.addEventListener('click', () => { if (!this.debugState) return; const result = selectDebugPatch(this.debugState, button.dataset.debugPatch ?? ''); this.showToast(result.message); this.render(); }));
    this.root.querySelector('[data-action="deploy-patch"]')?.addEventListener('click', () => { if (!this.debugState) return; const result = deployDebugPatch(this.debugState); this.showToast(result.message); if (result.outcome !== 'continue') this.finishDebugMission(result.outcome === 'victory'); this.render(); });
    this.root.querySelector('[data-action="debug-hint"]')?.addEventListener('click', () => { this.hintOpen = !this.hintOpen; this.render(); });
    this.root.querySelector('[data-action="close-debug-hint"]')?.addEventListener('click', () => { this.hintOpen = false; this.render(); });
    this.root.querySelector('[data-action="audio"]')?.addEventListener('click', () => { this.career.audioEnabled = !this.career.audioEnabled; this.audio.setEnabled(this.career.audioEnabled); saveCareer(this.career); this.render(); });
    this.root.querySelector('[data-action="locale"]')?.addEventListener('click', () => this.toggleLocale());
    this.root.querySelector('[data-action="text-size"]')?.addEventListener('click', () => this.toggleTextSize());
    this.root.querySelector('[data-action="report"]')?.addEventListener('click', async () => {
      const report = ['ROOT//PANIC DEBUG REPORT', 'MISSION: GHOST COMMIT', `EVIDENCE: ${this.debugState?.evidence.join(', ')}`, `PATCH: ${this.debugState?.selectedPatchId ?? '-'}`, `GRADE: ${this.game.result?.grade ?? '-'}`].join('\n');
      try { await navigator.clipboard.writeText(report); this.showToast(this.local('调试报告已复制。', 'Debug report copied.')); } catch { window.prompt(this.local('复制调试报告', 'Copy debug report'), report); }
    });
    this.bindMissionExitEvent();
    this.bindResultNavigationEvents();
  }

