import type { InteractionMissionState } from '../core/types';
import type { InteractionMissionDefinition } from '../data/interactionMissions';

const snapshot = (state: InteractionMissionState): InteractionMissionState['history'][number] => ({
  connections: [...state.connections],
  disabledEdges: [...state.disabledEdges],
  placements: { ...state.placements },
  order: [...state.order],
  controls: { ...state.controls },
});

const remember = (state: InteractionMissionState): void => {
  state.history.push(snapshot(state));
  state.history = state.history.slice(-30);
};

const pushLog = (state: InteractionMissionState, level: InteractionMissionState['logs'][number]['level'], message: string): void => {
  state.logs.unshift({ level, message });
  state.logs = state.logs.slice(0, 40);
};

export const createInteractionMission = (definition: InteractionMissionDefinition, duration = 420): InteractionMissionState => ({
  scenarioId: definition.scenarioId,
  elapsed: 0,
  duration,
  stability: 100,
  attempts: 0,
  connections: [...(definition.initialConnections ?? [])],
  disabledEdges: [],
  placements: {},
  order: [...(definition.initialOrder ?? definition.items?.map((item) => item.id) ?? [])],
  controls: Object.fromEntries((definition.controls ?? []).map((control) => [control.id, control.initial])),
  history: [],
  logs: [{ level: 'info', message: '交互沙箱已加载。完成目标后执行验证。' }],
});

export const tickInteractionMission = (state: InteractionMissionState, deltaSeconds: number): 'running' | 'defeat' => {
  state.elapsed += deltaSeconds;
  if (state.elapsed >= state.duration || state.stability <= 0) return 'defeat';
  return 'running';
};

export const toggleMissionEdge = (state: InteractionMissionState, definition: InteractionMissionDefinition, edgeId: string): { ok: boolean; message: string } => {
  const edge = definition.edges?.find((item) => item.id === edgeId);
  if (!edge) return { ok: false, message: '这两个节点之间不存在可用连接。' };
  remember(state);
  if (definition.kind === 'isolate') {
    if (state.disabledEdges.includes(edgeId)) {
      state.disabledEdges = state.disabledEdges.filter((id) => id !== edgeId);
      pushLog(state, 'info', `已恢复权限：${edge.label}`);
      return { ok: true, message: `已恢复 ${edge.label}` };
    }
    state.disabledEdges.push(edgeId);
    pushLog(state, 'warn', `已吊销权限：${edge.label}`);
    return { ok: true, message: `已吊销 ${edge.label}` };
  }
  if (state.connections.includes(edgeId)) {
    state.connections = state.connections.filter((id) => id !== edgeId);
    pushLog(state, 'warn', `链路已断开：${edge.label}`);
    return { ok: true, message: `已断开 ${edge.label}` };
  }
  state.connections.push(edgeId);
  pushLog(state, 'info', `链路已建立：${edge.label}`);
  return { ok: true, message: `已建立 ${edge.label}` };
};

export const toggleMissionEdgeBetween = (state: InteractionMissionState, definition: InteractionMissionDefinition, from: string, to: string): { ok: boolean; message: string } => {
  const edge = definition.edges?.find((item) => (item.from === from && item.to === to) || (item.from === to && item.to === from));
  return edge ? toggleMissionEdge(state, definition, edge.id) : { ok: false, message: '端口不兼容，无法建立这条连接。' };
};

export const placeMissionItem = (state: InteractionMissionState, definition: InteractionMissionDefinition, itemId: string, zoneId: string): { ok: boolean; message: string } => {
  const item = definition.items?.find((candidate) => candidate.id === itemId);
  const zone = definition.zones?.find((candidate) => candidate.id === zoneId);
  if (!item || !zone) return { ok: false, message: '无效的项目或目标区域。' };
  remember(state);
  state.placements[itemId] = zoneId;
  state.selectedItemId = undefined;
  pushLog(state, 'info', `${item.label} → ${zone.label}`);
  return { ok: true, message: `已放入“${zone.label}”` };
};

export const moveMissionItem = (state: InteractionMissionState, definition: InteractionMissionDefinition, itemId: string, direction: -1 | 1): { ok: boolean; message: string } => {
  if (definition.kind !== 'sequence') return { ok: false, message: '当前任务不支持排序。' };
  const index = state.order.indexOf(itemId);
  const target = index + direction;
  if (index < 0 || target < 0 || target >= state.order.length) return { ok: false, message: '已经到达边界。' };
  remember(state);
  [state.order[index], state.order[target]] = [state.order[target], state.order[index]];
  return { ok: true, message: '步骤顺序已调整。' };
};

export const reorderMissionItem = (state: InteractionMissionState, definition: InteractionMissionDefinition, itemId: string, beforeId: string): { ok: boolean; message: string } => {
  if (definition.kind !== 'sequence' || itemId === beforeId) return { ok: false, message: '无法调整该步骤。' };
  const from = state.order.indexOf(itemId);
  const target = state.order.indexOf(beforeId);
  if (from < 0 || target < 0) return { ok: false, message: '步骤不存在。' };
  remember(state);
  state.order.splice(from, 1);
  state.order.splice(state.order.indexOf(beforeId), 0, itemId);
  return { ok: true, message: '步骤已拖动到新位置。' };
};

export const setMissionControl = (state: InteractionMissionState, definition: InteractionMissionDefinition, controlId: string, value: number | boolean): { ok: boolean; message: string } => {
  const control = definition.controls?.find((candidate) => candidate.id === controlId);
  if (!control) return { ok: false, message: '控制器不存在。' };
  const normalized = control.type === 'toggle'
    ? Boolean(value)
    : Math.max(control.min ?? 0, Math.min(control.max ?? 100, Number(value)));
  if (state.controls[controlId] === normalized) return { ok: true, message: '参数保持不变。' };
  remember(state);
  state.controls[controlId] = normalized;
  pushLog(state, 'info', `${control.label} → ${control.type === 'toggle' ? (normalized ? 'ON' : 'OFF') : normalized}`);
  return { ok: true, message: `${control.label} 已调整` };
};

export const undoInteraction = (state: InteractionMissionState): boolean => {
  const previous = state.history.pop();
  if (!previous) return false;
  state.connections = previous.connections;
  state.disabledEdges = previous.disabledEdges;
  state.placements = previous.placements;
  state.order = previous.order;
  state.controls = previous.controls;
  return true;
};

export const resetInteraction = (state: InteractionMissionState, definition: InteractionMissionDefinition): void => {
  remember(state);
  state.connections = [...(definition.initialConnections ?? [])];
  state.disabledEdges = [];
  state.placements = {};
  state.order = [...(definition.initialOrder ?? definition.items?.map((item) => item.id) ?? [])];
  state.controls = Object.fromEntries((definition.controls ?? []).map((control) => [control.id, control.initial]));
  state.selectedItemId = undefined;
  state.selectedNodeId = undefined;
  pushLog(state, 'info', '交互面板已重置。');
};

export interface InteractionValidation {
  success: boolean;
  progress: number;
  issues: string[];
  message: string;
}

export const validateInteraction = (state: InteractionMissionState, definition: InteractionMissionDefinition): InteractionValidation => {
  const issues: string[] = [];
  let correct = 0;
  let total = 0;

  if (definition.kind === 'connect') {
    for (const edge of definition.requiredConnections ?? []) {
      total += 1;
      if (state.connections.includes(edge)) correct += 1;
      else issues.push(`缺少必要链路：${definition.edges?.find((item) => item.id === edge)?.label ?? edge}`);
    }
    for (const edge of definition.forbiddenConnections ?? []) {
      total += 1;
      if (!state.connections.includes(edge)) correct += 1;
      else issues.push(`危险链路仍然存在：${definition.edges?.find((item) => item.id === edge)?.label ?? edge}`);
    }
  } else if (definition.kind === 'isolate') {
    for (const edge of definition.requiredDisabledEdges ?? []) {
      total += 1;
      if (state.disabledEdges.includes(edge)) correct += 1;
      else issues.push(`攻击权限尚未吊销：${definition.edges?.find((item) => item.id === edge)?.label ?? edge}`);
    }
    for (const edge of definition.protectedEdges ?? []) {
      total += 1;
      if (!state.disabledEdges.includes(edge)) correct += 1;
      else issues.push(`关键业务权限被误删：${definition.edges?.find((item) => item.id === edge)?.label ?? edge}`);
    }
  } else if (definition.kind === 'classify' || definition.kind === 'allocate') {
    const solution = definition.solutionPlacements ?? {};
    for (const [itemId, zoneId] of Object.entries(solution)) {
      total += 1;
      if (state.placements[itemId] === zoneId) correct += 1;
      else if (!state.placements[itemId]) issues.push(`尚未分类：${definition.items?.find((item) => item.id === itemId)?.label ?? itemId}`);
      else issues.push(`分类错误：${definition.items?.find((item) => item.id === itemId)?.label ?? itemId}`);
    }
  } else if (definition.kind === 'sequence') {
    const solution = definition.correctOrder ?? [];
    total = solution.length;
    correct = state.order.reduce((count, id, index) => count + (solution[index] === id ? 1 : 0), 0);
    if (correct !== total) issues.push('执行顺序仍存在依赖冲突。');
  } else {
    for (const control of definition.controls ?? []) {
      total += 1;
      const value = state.controls[control.id];
      const matches = control.type === 'toggle'
        ? value === control.target
        : Math.abs(Number(value) - Number(control.target)) <= (control.tolerance ?? 0);
      if (matches) correct += 1;
      else issues.push(`${control.label} 尚未达到目标窗口`);
    }
  }

  const progress = total ? Math.round(correct / total * 100) : 0;
  const success = total > 0 && correct === total;
  if (success) {
    pushLog(state, 'success', '验证通过：所有约束均已满足。');
    return { success, progress, issues, message: '验证通过，任务目标已经完成。' };
  }
  state.attempts += 1;
  state.stability = Math.max(0, state.stability - Math.max(5, Math.min(18, issues.length * 3)));
  pushLog(state, 'critical', `验证失败：${issues[0] ?? '仍有未满足条件'}`);
  return { success, progress, issues: issues.slice(0, 4), message: `验证失败，当前完成度 ${progress}%` };
};
