import type { InteractionKind } from '../core/types';

export interface InteractionNodeDefinition {
  id: string;
  label: string;
  labelEn: string;
  x: number;
  y: number;
  role: string;
}

export interface InteractionEdgeDefinition {
  id: string;
  from: string;
  to: string;
  label: string;
  latency?: number;
  bandwidth?: number;
}

export interface InteractionItemDefinition {
  id: string;
  label: string;
  labelEn: string;
  detail: string;
  detailEn: string;
  tag?: string;
  cpu?: number;
  memory?: number;
}

export interface InteractionZoneDefinition {
  id: string;
  label: string;
  labelEn: string;
  description: string;
  descriptionEn: string;
  color: string;
  cpu?: number;
  memory?: number;
}

export interface InteractionControlDefinition {
  id: string;
  label: string;
  labelEn: string;
  detail: string;
  detailEn: string;
  type: 'toggle' | 'range';
  initial: number | boolean;
  target: number | boolean;
  min?: number;
  max?: number;
  step?: number;
  tolerance?: number;
  unit?: string;
}

export interface InteractionMissionDefinition {
  scenarioId: string;
  kind: InteractionKind;
  title: string;
  titleEn: string;
  objective: string;
  objectiveEn: string;
  instructions: string[];
  instructionsEn: string[];
  nodes?: InteractionNodeDefinition[];
  edges?: InteractionEdgeDefinition[];
  initialConnections?: string[];
  requiredConnections?: string[];
  forbiddenConnections?: string[];
  requiredDisabledEdges?: string[];
  protectedEdges?: string[];
  items?: InteractionItemDefinition[];
  zones?: InteractionZoneDefinition[];
  solutionPlacements?: Record<string, string>;
  initialOrder?: string[];
  correctOrder?: string[];
  controls?: InteractionControlDefinition[];
}

