export const getInteractionMission = (scenarioId: string): InteractionMissionDefinition | undefined => INTERACTION_MISSIONS.find((mission) => mission.scenarioId === scenarioId);
export const getInteractionItem = (mission: InteractionMissionDefinition, itemId: string): InteractionItemDefinition | undefined => mission.items?.find((item) => item.id === itemId);
export const getInteractionNode = (mission: InteractionMissionDefinition, nodeId: string): InteractionNodeDefinition | undefined => mission.nodes?.find((node) => node.id === nodeId);
